import PropTypes from "prop-types";
import { useState } from "react";
import { format } from "date-fns";
// @mui
import { useTheme } from "@mui/material/styles";
import {
  TableRow,
  Checkbox,
  TableCell,
  Typography,
  MenuItem,
  Stack
} from "@mui/material";
// utils
import { fDateTime } from "../../../../utils/formatTime";
import { fCurrency } from "../../../../utils/formatNumber";
// components
import Iconify from "../../../../components/Iconify";
import { TableMoreMenu } from "../../../../components/table";
import Label from "../../../../components/Label";
import { useTranslation } from "react-i18next";
//

// ----------------------------------------------------------------------

UserCommissionTableRow.propTypes = {
  row: PropTypes.object,
  selected: PropTypes.bool,
  onEditRow: PropTypes.func,
  onSelectRow: PropTypes.func,
  onDeleteRow: PropTypes.func,
  deleteText: PropTypes.string,
  editText: PropTypes.string,
};

export default function UserCommissionTableRow({
  row,
  selected,
  onEditRow,
  onSelectRow,
  onDeleteRow,
  deleteText = "Delete",
  editText = "Edit",
}) {
  const theme = useTheme();

  const { t } = useTranslation();

  const STATUS_CONFIG = {
    // SUCCESS
    COMPLETE: {
      level: "success",
      icon: "eva:checkmark-circle-fill",
    },
    F: {
      level: "success",
      icon: "mdi:check-decagram",
    },
    PAID: {
      level: "success",
      icon: "eva:checkmark-circle-fill",
    },

    // WARNING
    PENDING: {
      level: "warning",
      icon: "eva:clock-outline",
    },
    P: {
      level: "warning",
      icon: "eva:clock-outline",
    },
    N: {
      level: "warning",
      icon: "eva:clock-outline",
    },
    R: {
      level: "warning",
      icon: "eva:clock-outline",
    },
    PENDING_ACTIVATION: {
      level: "warning",
      icon: "eva:clock-outline",
    },

    // ERROR
    FAILED: {
      level: "error",
      icon: "eva:close-circle-fill",
    },
    I: {
      level: "error",
      icon: "eva:close-circle-fill",
    },
    A: {
      level: "error",
      icon: "eva:close-circle-fill",
    },
    CANCELED: {
      level: "error",
      icon: "eva:close-circle-fill",
    },
    INCIDENCE: {
      level: "error",
      icon: "eva:close-circle-fill",
    },
    REJECTED: {
      level: "error",
      icon: "eva:close-circle-fill",
    },
  };

  const DEFAULT_ICON = "eva:minus-circle-outline";
  const DEFAULT_LEVEL = "default";

  const cfg = STATUS_CONFIG[row.transaction_status] || {};
  const level = cfg.level || DEFAULT_LEVEL;
  const icon = cfg.icon || DEFAULT_ICON;

  const iconColor =
    level === "success"
      ? "success.main"
      : level === "warning"
      ? "warning.main"
      : level === "error"
      ? "error.main"
      : "grey.500";

  const [openMenu, setOpenMenuActions] = useState(null);

  const handleOpenMenu = (event) => {
    setOpenMenuActions(event.currentTarget);
  };

  const handleCloseMenu = () => {
    setOpenMenuActions(null);
  };

  return (
    <TableRow hover selected={selected}>
      <TableCell padding="checkbox" />

      <TableCell align="left">{row?.ref_code}</TableCell>

      <TableCell align="center">{row?.full_name || "-"}</TableCell>
      <TableCell align="center">{t(`type_transaction.${row.type_transaction}`)}</TableCell>
      <TableCell align="center">{fDateTime(row?.created_on)}</TableCell>
      <TableCell align="center">
        {fCurrency(row?.amount)} {row?.currency}
      </TableCell>
      <TableCell align="center">
        {fCurrency(row?.newAmount)} {row?.currency}
      </TableCell>

      <TableCell align="center">
        <Stack
          direction="row"
          spacing={1}
          alignItems="center"
          justifyContent="center"
        >
          <Iconify
            icon={icon}
            sx={{
              width: 20,
              height: 20,
              color: iconColor,
            }}
          />

          <Label
            variant={theme.palette.mode === "light" ? "ghost" : "filled"}
            color={level}
            sx={{ textTransform: "capitalize" }}
          >
            {t(`remesas.status_transac.${row.transaction_status}`)}
          </Label>
        </Stack>
      </TableCell>
    </TableRow>
  );
}
