import PropTypes from "prop-types";
// @mui
import {
  Tooltip,
  Stack,
  InputAdornment,
  TextField,
  Autocomplete,
  Paper,
} from "@mui/material";
import { LoadingButton } from "@mui/lab";
import { DatePicker } from "@mui/x-date-pickers/DatePicker";
// components
import Iconify from "../../../../components/Iconify";
import CurrencyPopover from "src/layouts/dashboard/header/CurrencyPopover";
import { useTranslation } from "react-i18next";

// ----------------------------------------------------------------------
const INPUT_WIDTH = 200;
const CONTROL_ITEM_SX = {
  textTransform: "capitalize",
  maxWidth: { md: INPUT_WIDTH },
  flex: "1 1 220px",
  minWidth: 180,
};
const DATE_PICKER_SX = {
  flex: "1 1 220px",
  minWidth: 200,
};
const FIELD_STYLE = {
  borderRadius: 3,
  backgroundColor: (theme) => theme.palette.background.paper,
  "& .MuiOutlinedInput-notchedOutline": {
    borderColor: "rgba(145, 158, 171, 0.32)",
  },
};
const SEARCH_FIELD_SX = {
  ...FIELD_STYLE,
  flex: "1 1 0%",
  minWidth: 260,
};

TransactionTableToolbar.propTypes = {
  isLoading: PropTypes.bool,
  filterUser: PropTypes.string,
  filterEndDate: PropTypes.instanceOf(Date),
  filterStartDate: PropTypes.instanceOf(Date),
  filterName: PropTypes.string,
  placeholder: PropTypes.string,
  loadText: PropTypes.string,
  title: PropTypes.string,
  onFilterName: PropTypes.func,
  onFilterEndDate: PropTypes.func,
  onFilterUser: PropTypes.func,
  onFilterStartDate: PropTypes.func,
  users: PropTypes.array,
  handleRefresh: PropTypes.func,
};

export default function TransactionTableToolbar({
  users,
  filterName,
  filterUser,
  filterStartDate,
  filterEndDate,
  onFilterName,
  handleRefresh,
  onFilterUser,
  onFilterStartDate,
  onFilterEndDate,
  isLoading,
  placeholder = "Search ...",
  loadText = "Load",
  title = "Filter list",
}) {
  const { t } = useTranslation();
  const allUsersOption = { uid: "", full_name: t("params.all") };
  const selectedUser =
    filterUser === ""
      ? allUsersOption
      : users?.find((usr) => usr.uid === filterUser) || null;
  return (
    <Paper
      elevation={0}
      sx={{
        p: { xs: 2, md: 3 },
        boxShadow: 0,
        backgroundColor: "background.default",
      }}
    >
      <Stack spacing={2}>
        <Stack direction="row" spacing={2} flexWrap="wrap" alignItems="center">
          <CurrencyPopover />
          <Autocomplete
            options={[allUsersOption, ...(users ?? [])]}
            value={selectedUser}
            onChange={(_, newValue) =>
              onFilterUser({ target: { value: newValue?.uid ?? "" } })
            }
            isOptionEqualToValue={(option, value) => option?.uid === value?.uid}
            getOptionLabel={(option) => option?.full_name ?? ""}
            ListboxProps={{
              sx: { maxHeight: 260 },
            }}
            sx={{
              ...CONTROL_ITEM_SX,
              flexBasis: 240,
            }}
            renderInput={(params) => (
              <TextField
                {...params}
                label={t("field.user")}
                sx={{ ...FIELD_STYLE, textTransform: "capitalize" }}
              />
            )}
          />
          <TextField
            value={filterName}
            onChange={(event) => onFilterName(event.target.value)}
            placeholder={placeholder}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <Iconify
                    icon={"eva:search-fill"}
                    sx={{ color: "text.disabled", width: 20, height: 20 }}
                  />
                </InputAdornment>
              ),
            }}
            sx={SEARCH_FIELD_SX}
            fullWidth
          />
        </Stack>

        <Stack
          direction="row"
          spacing={2}
          flexWrap="wrap"
          alignItems="center"
          justifyContent="space-between"
        >
          <Stack
            direction="row"
            spacing={2}
            flex="1 1 auto"
            flexWrap="wrap"
            alignItems="center"
          >
            <DatePicker
              label={t("field.start_date")}
              value={filterStartDate}
              onChange={onFilterStartDate}
              sx={DATE_PICKER_SX}
              renderInput={(params) => (
                <TextField {...params} fullWidth sx={FIELD_STYLE} />
              )}
            />
            <DatePicker
              label={t("field.end_date")}
              value={filterEndDate}
              onChange={onFilterEndDate}
              sx={DATE_PICKER_SX}
              renderInput={(params) => (
                <TextField {...params} fullWidth sx={FIELD_STYLE} />
              )}
            />
          </Stack>
          <Stack direction="row" spacing={2} alignItems="center">
            <Tooltip title={title}>
              <span>
                <LoadingButton
                  startIcon={<Iconify icon={"ic:round-filter-list"} />}
                  variant="contained"
                  onClick={handleRefresh}
                  loading={isLoading}
                  size="large"
                >
                  {loadText}
                </LoadingButton>
              </span>
            </Tooltip>
          </Stack>
        </Stack>
      </Stack>
    </Paper>
  );
}
